    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 warpTime) public {
        vm.assume(value > 0);
        vm.assume(warpTime > 0);
        // Ensure block.timestamp > pastBlockTime (initially 0) after warping
        vm.warp(warpTime);
        // Fund a fresh address to avoid balance issues
        address caller = address(0x1234);
        vm.deal(caller, value);
        vm.prank(caller);
        try c{value: value}() {
