import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzz_timestamp, uint256 fuzz_roll1, uint256 fuzz_roll2) public {
        vm.assume(fuzz_timestamp > 0 && fuzz_timestamp < type(uint64).max);
        vm.assume(fuzz_roll1 < type(uint256).max && fuzz_roll2 < type(uint256).max);
        vm.assume(fuzz_roll1 != fuzz_roll2);
        vm.assume(fuzz_roll1 % 15 != 0);
        vm.assume(fuzz_roll2 % 15 != 0);

        // First call
        vm.warp(fuzz_timestamp);
        vm.roll(fuzz_roll1);
        address alice = address(0x1000);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.fallback{value: 10 ether}();
        uint256 pastAfterFirst = c.pastBlockTime();

        // Second call with same timestamp but different block number
        vm.warp(fuzz_timestamp);
        vm.roll(fuzz_roll2);
        address bob = address(0x2000);
        vm.deal(bob, 10 ether);
        vm.prank(bob);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Assert: the reference requires strict > so second call must revert; buggy allows >= so it may succeed
        if (pastAfterFirst == fuzz_timestamp) {
            // If first call updated pastBlockTime to fuzz_timestamp, second call with same timestamp must fail in reference
            assertTrue(!success);
        } else {
            // If first call did not update (should not happen), skip
            assertTrue(true);
        }
    }
}

