import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTime, uint256 rollNum) public {
        // Restrict inputs to admissible domain: timestamps must be non-zero after the first call, block numbers positive.
        vm.assume(warpTime > 0);
        vm.assume(rollNum > 0);

        // Set block timestamp and number for the first fallback call.
        vm.warp(warpTime);
        vm.roll(rollNum);

        // Prepare sender with required ether.
        address sender = makeAddr("sender");
        vm.deal(sender, 20 ether);

        // First fallback call: must succeed because pastBlockTime is 0 and msg.value is 10 ether.
        vm.prank(sender);
        c.fallback{value: 10 ether}();
        uint256 firstPastBlockTime = c.pastBlockTime();

        // Second fallback call: keep the same block timestamp to expose the bug.
        // The buggy version allows this because of >= check, original reverts due to > check.
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        if (ok) {
            // If the call succeeded, the contract's pastBlockTime must have INCREASED strictly.
            uint256 secondPastBlockTime = c.pastBlockTime();
            assertTrue(firstPastBlockTime < secondPastBlockTime);
        }
        // If the call reverted, the property vacuously holds (we only assert on success).
    }
}

