pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestampDelta, uint128 blockNum1, uint128 blockNum2) public {
        // Keep timestamps in a wide admissible range; ensure two distinct timestamps can be chosen.
        vm.assume(timestampDelta > 0 && timestampDelta < 365 days);
        uint256 t1 = 1_000_000 + timestampDelta;
        uint256 t2 = t1; // same timestamp for the two calls (adversarial)
        vm.assume(blockNum1 != blockNum2);

        // Set up sender with enough Ether for two fallback calls (10 ether each).
        address actor = address(0x123);
        vm.deal(actor, 100 ether);

        // First call at block number blockNum1, timestamp t1.
        vm.roll(blockNum1);
        vm.warp(t1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");
        uint256 pastAfterFirst = c.pastBlockTime();

        // Second call at block number blockNum2, same timestamp t2 = t1.
        // The original requires block.timestamp > pastBlockTime, so this must revert.
        // The mutant allows block.timestamp >= pastBlockTime, so it may succeed.
        vm.roll(blockNum2);
        vm.warp(t2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // PROPERY: If the second call succeeds, the new pastBlockTime must be strictly greater
        // than the value after the first call.
        if (ok2) {
            uint256 pastAfterSecond = c.pastBlockTime();
            assertTrue(pastAfterSecond > pastAfterFirst);
        } else {
            // Second call reverted: as expected by the original. No violation.
            // The property is vacuous when ok2 is false, so we simply pass.
            assertTrue(true);
        }
    }
}

