pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTime) public {
        // warpTime must be > 0 to satisfy the require in the reference and also be a valid timestamp
        vm.assume(warpTime > 0);

        // Warp to a future time and set block number to 1 (not divisible by 15) to avoid ether transfer
        vm.warp(warpTime);
        vm.roll(1);

        // Make the first call with 10 ether from the test contract (as an EOA)
        address actor = address(this);
        vm.deal(actor, 10 ether);
        c.f{value: 10 ether}();

        // Record pastBlockTime after the first call
        uint256 timeAfterFirst = c.pastBlockTime();

        // Make a second call at the exact same timestamp and block number
        // In the reference, this will revert because block.timestamp == pastBlockTime
        // In the mutant, it will succeed
        vm.deal(actor, 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        if (success) {
            // If the call succeeded, pastBlockTime must have been updated to exactly warpTime
            // The mutant updates pastBlockTime again, so it should equal warpTime
            // The property: if the call succeeds, pastBlockTime must be strictly > timeAfterFirst
            // Since warpTime == timeAfterFirst, this must be false, meaning a successful call
            // would violate the invariant that pastBlockTime strictly increases
            assertTrue(c.pastBlockTime() > timeAfterFirst);
        } else {
            // Reference behaviour: call reverts as expected
            // The property holds vacuously (or we can just assert the revert)
            assertTrue(c.pastBlockTime() == timeAfterFirst);
        }
    }
}

