pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 block1, uint256 block2, uint256 time1, uint256 time2) public {
        // Admissible domain: block numbers non-negative; block2 > block1 so orders are fixed;
        // timestamps increasing to satisfy the require, and time2 > time1.
        vm.assume(block2 > block1);
        vm.assume(time2 > time1);
        // block2 must be a multiple of 15 to trigger the transfer in the second call.
        vm.assume(block2 % 15 == 0);

        address actor = address(0xB0B);
        vm.deal(actor, 20 ether);

        // First call with 10 ether, block1 and time1
        vm.roll(block1);
        vm.warp(time1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");

        // Second call with 10 ether, block2 and time2
        vm.roll(block2);
        vm.warp(time2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // Adversarial counterparty: if the second call does not revert, the transfer is to the actor (EOA),
        // which always succeeds. So no helper is needed; the low-level call to actor succeeds.
        // The property: after two successful fallback calls with the second block satisfying the condition,
        // the contract must have zero balance.
        if (ok2) {
            assertTrue(address(c).balance == 0);
        } else {
            // The buggy version reverts on the second call, leaving balance > 0.
            // This assertion checks that a revert on the second call should not happen in the reference.
            assertTrue(false);
        }
    }
}

