pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpDelta) public {
        // Keep block timestamp strictly positive and avoid overflow in addition
        vm.assume(warpDelta > 0 && warpDelta < 2**64);

        // Set up a clean timestamp that is > 0 so the initial pastBlockTime (0) is behind it
        uint256 freshTS = 1 + warpDelta;
        vm.warp(freshTS);

        // Make the fuzzer call as msg.sender; it needs exactly 10 ether
        address caller = address(0xA5CD91E65FB56F2F6BD848E546B259249C6F1695);
        vm.deal(caller, 10 ether);
        vm.prank(caller);

        uint256 oldPast = c.pastBlockTime();
        bool ok;
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 newPast = c.pastBlockTime();

        // Universal property: on success, pastBlockTime must have advanced strictly beyond its old value
        // and must equal the current block timestamp.
        // Bug: always reverts, so ok remains false, newPast stays equal to oldPast.
        assertTrue(
            (!ok) ||
            (newPast == block.timestamp && newPast > oldPast),
            "Fallback should succeed and update pastBlockTime to cur ts"
        );
    }
}
